import {
  ComboboxInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxList,
  ComboboxItem,
  Combobox,
} from "@/registry/erbium/ui/combobox";

export const defaultProps = {
  autoHighlight: false,
  disabled: false,
  placeholder: "Select a framework",
  showClear: false,
  showTrigger: true,
} satisfies {
  placeholder: string;
  disabled: boolean;
  showTrigger: boolean;
  showClear: boolean;
  autoHighlight: boolean;
};

export default function ComboboxPlaygroundExample(
  args: {
    placeholder: string;
    disabled: boolean;
    showTrigger: boolean;
    showClear: boolean;
    autoHighlight: boolean;
  } = defaultProps,
) {
  return (
    <Combobox items={["React", "Vue", "Svelte"]} autoHighlight={args.autoHighlight}>
      <ComboboxInput
        placeholder={args.placeholder}
        disabled={args.disabled}
        showTrigger={args.showTrigger}
        showClear={args.showClear}
      />
      <ComboboxContent>
        <ComboboxEmpty>No results.</ComboboxEmpty>
        <ComboboxList>
          {(item: string) => (
            <ComboboxItem key={item} value={item}>
              {item}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  );
}
